{
  "queries": [
    {
      "doc_id": "SOP-P1-L3-02: Product changeover - Machining line",
      "query": "Please provide the latest revision history and approval signatures for this SOP, and identify any required temporary controls during product changeover that are not documented."
    },
    {
      "doc_id": "QS-CFW-5042-83: Quality specification - valve body CFW-5042-83 (F316)",
      "query": "Audit request: list all critical-to-quality characteristics and the evidence required (inspection reports, calibration records) to demonstrate conformance for F316 valve bodies."
    },
    {
      "doc_id": "QS-PROC-06: Forging temperature control (P2)",
      "query": "Explain how target temperature ranges and allowable excursions are defined and what records must be retained to demonstrate compliance for P2 forgings."
    },
    {
      "doc_id": "SOP-P3-L1-05: Planned shutdown - Hot Forge line",
      "query": "What are the sign-off checkpoints and responsible roles during a planned shutdown? Provide the checklist items that require documented evidence for audit."
    },
    {
      "doc_id": "SOP-P2-L1-04: Shift handover - Hot Forge line",
      "query": "Request: show the handover form template and describe controls to ensure critical process parameters are communicated between shifts; any known gaps should be noted."
    },
    {
      "doc_id": "SOP-P2-L2-03: First-article inspection - Ring Rolling line",
      "query": "For first-article inspections on the Ring Rolling line, what acceptance criteria and sampling are specified, and what records (including inspector approval) are mandatory?"
    },
    {
      "doc_id": "SOP-P2-L4-03: First-article inspection - Heat Treat line",
      "query": "Identify the sequence of verifications required for first-article on Heat Treat, who approves release for production, and what documentary evidence must accompany release."
    },
    {
      "doc_id": "QS-CFW-4713-78: Quality specification - axle hub CFW-4713-78 (4140)",
      "query": "Provide the non-conformance disposition options listed for axle hubs and the required documentation for each disposition path."
    },
    {
      "doc_id": "SOP-P1-L3-03: First-article inspection - Machining line",
      "query": "Ask for the form used for first-article acceptance on Machining line, and whether in-process measurement data must be attached for audit traceability."
    },
    {
      "doc_id": "ECN-2026-027: Change notice - Hot Forge induction billet heater #3",
      "query": "Please provide the justification for this ECN, list the approved changes, and supply pre- and post-change validation evidence and approval signatures."
    },
    {
      "doc_id": "ECN-2026-005: Change notice - Machining induction billet heater #1",
      "query": "What risk assessment and testing were completed prior to implementation of this ECN, and where are the resulting test records stored?"
    },
    {
      "doc_id": "ECN-2026-021: Change notice - Machining hydraulic forging press #2",
      "query": "For this change, identify any updates required to related SOPs or training records and provide evidence that affected personnel were informed and trained."
    },
    {
      "doc_id": "SOP-P3-L1-04: Shift handover - Hot Forge line",
      "query": "Compare this version of the shift handover procedure with SOP-P2-L1-04 and highlight any differences in required documentation or approvals."
    },
    {
      "doc_id": "SOP-P1-L2-04: Shift handover - Ring Rolling line",
      "query": "Request: provide the handover log template and describe how critical machine settings are verified and recorded during shift change."
    },
    {
      "doc_id": "QS-CFW-8165-49: Quality specification - flange blank CFW-8165-49 (4140)",
      "query": "During audit, what objective evidence is acceptable to demonstrate chemical composition and mechanical property compliance for 4140 flange blanks?"
    },
    {
      "doc_id": "SOP-P3-L2-05: Planned shutdown - Ring Rolling line",
      "query": "What are the required preservation and inspection steps after a planned shutdown before restart, and which records must be completed to evidence readiness?"
    },
    {
      "doc_id": "ECN-2026-050: Change notice - Ring Rolling radial ring rolling mill #3",
      "query": "Provide the implementation plan, post-implementation monitoring criteria, and where monitoring data will be retained for audit review."
    },
    {
      "doc_id": "ECN-2026-049: Change notice - Heat Treat hydraulic forging press #3",
      "query": "What corrective actions or preventive measures were identified during the ECN review, and show the verification records that these were completed."
    },
    {
      "doc_id": "QS-CFW-1159-60: Quality specification - track link CFW-1159-60 (15B37)",
      "query": "Clarify the specified inspection points for track links and the acceptance criteria; what documentation is required to release a lot?"
    },
    {
      "doc_id": "SOP-P2-L2-02: Product changeover - Ring Rolling line",
      "query": "Detail the required pre-changeover approvals, tooling verification steps, and the records an auditor should expect to find demonstrating a conforming changeover."
    }
  ]
}
